  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 96: How much iodine does your toddler need, and where does it come from?
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   96,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'How much iodine does your toddler need, and where does it come from?',
   '"Iodine supports your toddler''s thyroid and brain development. Salt that is labelled iodized is an important source, while dairy, eggs, fish and iodine-fortified foods may also contribute. Adequacy depends on the foods and portions the child actually consumes — there is no need to add extra salt or start an iodine supplement independently."',
   'Iodine needs are small at this age: a commonly used reference for children aged one to three is about 90 micrograms a day, and India''s own guidance lines up closely with this figure — unlike calcium or protein earlier in this series, there isn''t a meaningful gap between Indian and international references here. Iodine''s job is to support thyroid hormone production, which in turn supports brain development in early childhood; this is why iodine deficiency during pregnancy and the toddler years is taken seriously as a public-health issue. That said, whether an individual toddler''s intake is actually adequate depends on the specific foods eaten and how much of each — it isn''t something that can be assumed automatically. Many plant-based drinks contain little iodine unless iodine has been added, and calcium or vitamin D fortification does not automatically mean iodine is present. If your child uses a plant drink, check the nutrition label specifically for iodine. A dairy-free or vegan diet can still provide adequate iodine through appropriately iodized salt or suitable fortified foods, but the overall pattern may need closer attention. Soy foods, cabbage and cauliflower do not need to be restricted when iodine intake is adequate. This series has already suggested keeping a toddler''s salt intake modest, and that guidance still holds. Choose packaged salt that is clearly labelled "iodized." Do not assume that rock salt, sea salt, specialty salt or an unpackaged product contains iodine — check the label rather than relying on the salt''s name or appearance. Store iodized salt in a closed container away from moisture and excessive heat, and use only a modest amount in ordinary family cooking. If practical for the recipe, adding it later may reduce iodine loss, but there is no need to add extra salt or separately salt the toddler''s food. For most toddlers, no iodine supplement is needed. Universal salt iodization is the main public-health strategy used to reduce iodine deficiency, but an individual child''s intake still depends on the household products and foods actually used. A supplement may be worth discussing when the child''s regular diet has no dependable iodine source — for example, the household does not use iodized salt and no routinely consumed food is specifically fortified with iodine. Do not begin supplementation without individual guidance. Iodine also has an upper limit — around 200 micrograms a day at this age — though this is a safety ceiling, not a recommended intake target. Excess iodine can also affect thyroid function. Do not give iodine drops, iodine-containing supplements, kelp or seaweed products to a toddler unless specifically advised. Ordinary mixed meals are unlikely to provide excessive iodine, but seaweed products are an important exception because their iodine content can be very high and unpredictable. Using this shared menu These are family meal ideas: serve the mother an appropriate adult portion, and any medical-condition notes below apply to her, not the toddler — "if you''re still hungry" also refers to the mother. Several meals naturally include iodized salt used in ordinary cooking, along with dairy; there''s no need to add anything extra.',
   'A note on dairy-free and vegan diets: if your child follows a vegan or dairy-free diet, uses a plant drink as the primary milk alternative, or your household does not use salt labelled iodized, check whether any regular food is fortified with iodine. If no dependable iodine source is present, discuss the overall pattern with the child''s clinician before using a supplement. If you manage diabetes: continue your prescribed meal, monitoring and medication schedule as usual — this week''s focus on your child''s iodine intake doesn''t change what you do for yourself. If you manage high blood pressure: keep added salt, pickles, papad and packaged sauces within the limits advised for you; when seasoning your own food, choose a salt clearly labelled iodized rather than assuming any particular salt type is iodine-free or iodine-containing by default. If you take thyroid medication: continue it exactly as prescribed — this week''s focus on your toddler''s iodine intake doesn''t change your own treatment — and maintain any required separation from iron or calcium supplements. Use a modest amount of salt clearly labelled iodized in ordinary family cooking, and check the labels of any dairy-free alternatives. There is no need to count iodine separately or add a supplement unless individual guidance indicates one.',
   'Where a meat, fish or egg option appears, it is optional — choose the vegetarian alternative freely. Cook them all the way through, keep chicken boneless and finely shredded, and keep fish meticulously deboned and finely flaked; this week''s fish choice (tilapia) is optional too, so use chicken, egg or a vegetarian option instead if you''d rather. Chicken is included as an ordinary protein choice rather than an iodine source. Fish may contribute iodine, but its amount varies and should not replace checking that the child has a dependable dietary source.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Iodine needs are small at this age: a commonly used reference for children aged one to three is about 90 micrograms a day, and India''s own guidance lines up closely with this figure — unlike calcium or protein earlier in this series, there isn''t a meaningful gap between Indian and international references here. Iodine''s job is to support thyroid hormone production, which in turn supports brain development in early childhood; this is why iodine deficiency during pregnancy and the toddler years is taken seriously as a public-health issue. That said, whether an individual toddler''s intake is actually adequate depends on the specific foods eaten and how much of each — it isn''t something that can be assumed automatically.", "breakfast_a": "Vegetable upma with a mild coconut chutney", "breakfast_b": "Vegetable upma with a fully cooked hard-boiled egg, finely chopped", "lunch_a": "Rice with a moong dal and soft-cooked pumpkin", "lunch_b": "Rice with boneless, finely shredded chicken and soft-cooked pumpkin", "nourishment_break_a": "A small bowl of curd with mashed ripe chikoo", "nourishment_break_b": "A small bowl of curd with grated paneer and a pinch of finely ground fennel (saunf) powder", "dinner_a": "Soft khichdi with a masoor dal and soft-cooked snake gourd", "dinner_b": "Soft khichdi with a mild tilapia curry, fully cooked, meticulously deboned and finely flaked, and soft-cooked snake gourd", "still_hungry": "A small bowl of dal"}, {"day_number": 2, "title": "Everyday sources and why labels matter", "notes": "Salt labelled iodized is an important and relatively dependable household source when used in ordinary, modest amounts. Milk, curd, paneer, eggs and fish may also contribute, but their iodine content can vary and should not be treated as a fixed amount. There is no need to calculate iodine meal by meal or add more salt specifically for iodine.", "breakfast_a": "Vegetable dalia with a mild curd side", "breakfast_b": "Vegetable dalia with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft roti with a chana dal and soft-cooked cabbage", "lunch_b": "Soft roti with boneless, finely shredded chicken and soft-cooked cabbage", "nourishment_break_a": "A small bowl of curd with grated paneer and a pinch of coriander (dhania) powder", "nourishment_break_b": "A small bowl of dal with grated paneer and a pinch of ajwain", "dinner_a": "Rice with a moong dal and soft-cooked lauki", "dinner_b": "Rice with boneless, finely shredded chicken and soft-cooked lauki", "still_hungry": "A small bowl of curd"}, {"day_number": 3, "title": "Checking iodine sources in dairy-free diets", "notes": "Many plant-based drinks contain little iodine unless iodine has been added, and calcium or vitamin D fortification does not automatically mean iodine is present. If your child uses a plant drink, check the nutrition label specifically for iodine. A dairy-free or vegan diet can still provide adequate iodine through appropriately iodized salt or suitable fortified foods, but the overall pattern may need closer attention. Soy foods, cabbage and cauliflower do not need to be restricted when iodine intake is adequate. In these dairy-free meals, any iodine contribution comes from modest use of salt clearly labelled iodized or from a product whose label specifically confirms iodine fortification — not from assuming that tofu or an ordinary plant drink contains iodine.", "breakfast_a": "Idli with a mild sambar", "breakfast_b": "Idli with a fully cooked egg bhurji on the side", "lunch_a": "Soft khichdi with a toor dal and soft-cooked cauliflower", "lunch_b": "Soft khichdi with a mild tilapia curry, fully cooked, meticulously deboned and finely flaked, and soft-cooked cauliflower", "nourishment_break_a": "Mashed ripe papaya with a smooth nut or seed paste, only if the ingredient has already been introduced safely", "nourishment_break_b": "A small bowl of dal with calcium-set tofu finely mashed through it", "dinner_a": "Rice with a sambar and soft-cooked cabbage", "dinner_b": "Rice with a mild egg curry, fully cooked, and soft-cooked cabbage", "still_hungry": "A small bowl of dal"}, {"day_number": 4, "title": "Keeping salt modest without losing iodine", "notes": "This series has already suggested keeping a toddler''s salt intake modest, and that guidance still holds. Choose packaged salt that is clearly labelled \"iodized.\" Do not assume that rock salt, sea salt, specialty salt or an unpackaged product contains iodine — check the label rather than relying on the salt''s name or appearance. Store iodized salt in a closed container away from moisture and excessive heat, and use only a modest amount in ordinary family cooking. If practical for the recipe, adding it later may reduce iodine loss, but there is no need to add extra salt or separately salt the toddler''s food.", "breakfast_a": "Ragi dosa with a mild tomato chutney", "breakfast_b": "Ragi dosa with a fully cooked hard-boiled egg, finely mashed", "lunch_a": "Soft roti with a masoor dal and soft-cooked methi (fenugreek) leaves", "lunch_b": "Soft roti with boneless, finely shredded chicken and soft-cooked methi (fenugreek) leaves", "nourishment_break_a": "A small bowl of curd with mashed ripe pear", "nourishment_break_b": "A small bowl of dal with grated paneer and a pinch of dried mint (pudina)", "dinner_a": "Rice with a chana dal and soft-cooked beans (french beans)", "dinner_b": "Rice with boneless, finely shredded chicken and soft-cooked beans (french beans)", "still_hungry": "A small bowl of curd"}, {"day_number": 5, "title": "Supplements aren''t the default", "notes": "For most toddlers, no iodine supplement is needed. Universal salt iodization is the main public-health strategy used to reduce iodine deficiency, but an individual child''s intake still depends on the household products and foods actually used. A supplement may be worth discussing when the child''s regular diet has no dependable iodine source — for example, the household does not use iodized salt and no routinely consumed food is specifically fortified with iodine. Do not begin supplementation without individual guidance. Iodine also has an upper limit — around 200 micrograms a day at this age — though this is a safety ceiling, not a recommended intake target. Excess iodine can also affect thyroid function. Do not give iodine drops, iodine-containing supplements, kelp or seaweed products to a toddler unless specifically advised. Ordinary mixed meals are unlikely to provide excessive iodine, but seaweed products are an important exception because their iodine content can be very high and unpredictable.", "breakfast_a": "Besan cheela with a mild mint chutney", "breakfast_b": "Besan cheela with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft khichdi with a moong dal and soft-cooked carrot, finely grated and cooked soft", "lunch_b": "Soft khichdi with boneless, finely shredded chicken and soft-cooked carrot, finely grated and cooked soft", "nourishment_break_a": "A small bowl of curd with mashed ripe mango, pulp only", "nourishment_break_b": "A small bowl of dal with grated paneer and a pinch of amchur (dry mango powder)", "dinner_a": "Rice with a sambar and soft-cooked ridge gourd (turai)", "dinner_b": "Rice with boneless, finely shredded chicken and soft-cooked ridge gourd (turai)", "still_hungry": "A small bowl of dal"}, {"day_number": 6, "title": "A gentle habit, not a rule", "notes": "There is no need to count iodine every day. Check that the household salt is labelled iodized, use it only in ordinary modest amounts, and notice whether your child has any other dependable sources, particularly when dairy is excluded. Do not add extra salt or begin a supplement simply to reach a number. Iodized salt can provide a dependable foundation, while dairy, eggs, fish or iodine-fortified foods may contribute according to the family''s diet. Adequacy should not be assumed solely because one of these foods appears occasionally.", "breakfast_a": "Oats chilla with a mild coriander chutney", "breakfast_b": "Oats chilla with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft roti with a moong dal and soft-cooked capsicum", "lunch_b": "Soft roti with boneless, finely shredded chicken and soft-cooked capsicum", "nourishment_break_a": "A small bowl of curd with mashed ripe banana and a pinch of cardamom", "nourishment_break_b": "A small bowl of dal with grated paneer and very finely ground curry leaves stirred in", "dinner_a": "Soft khichdi with a masoor dal and soft-cooked beetroot", "dinner_b": "Soft khichdi with boneless, finely shredded chicken and soft-cooked beetroot", "still_hungry": "A small bowl of curd"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. Looking back at the week, was the salt used at home clearly labelled iodized, and — if your child follows a dairy-free diet — did you check whether any regular alternative specifically contained iodine?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'Iodine does not require daily counting, but it does require one dependable source. Checking the salt label and any dairy-free substitute is a small household habit that supports your toddler''s thyroid and development.',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: small, steady adjustments serve your child''s nourishment better than any single rule enforced all at once.')
